INSERT INTO `certifications` (`id`, `id_mhs`, `title`, `start_date`, `end_date`, `description`, `institution`, `attachment`, `created_at`, `updated_at`) VALUES
(184, '4312001085', 'R fundamental for data science', '2021-01-01', NULL, 'Learning Outcome\r\nModul ini akan membahas bahasa R - bahasa pemrograman yang sangat populer di bidang data science - disusun dengan isi yang lugas, mudah dicerna dan lengkap dengan contoh.\r\n\r\nMateri yang dipelajari :\r\nLet’s Get Started with R\r\nVector, List, and Data Frame\r\nChart and Graphic', 'dqlab', 'https://academy.dqlab.id/Certificate_check_2/resultV2/DQLABINTR1NDNKEV', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(185, '4312001085', 'Data Visualization in Data Science using R', '2021-01-01', NULL, 'Learning Outcome\r\nKuasai keterampilan membuat komposisi grafik visualisasi data dasar yang informatif dan menarik dengan menggunakan package ggplot2 di R.\r\n\r\nMateri yang dipelajari :\r\nMengenal ggplot2\r\nDasar \"Kanvas\" untuk Grafik\r\nData dan Aesthetic Mapping\r\nLayer untuk Grafik Pertama: Scatter Plot\r\nHistogram\r\nVisualisasi Trend dengan Line Chart\r\nBar Chart dan Pie Chart\r\nMembagi Grafik dengan Faceting\r\nPenutu', 'dqlab', 'https://academy.dqlab.id/Certificate_check_2/resultV2/DQLABDTVISVKJSUE', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(186, '4312001085', 'Data Preparation in Data Science using R', '2021-01-01', NULL, 'Learning Outcome\r\nKuasai keterampilan data preparation atau data wrangling ini langkah demi langkah - dengan fokus pada transformasi struktur dari file dataset kependudukan DKI Jakarta.\r\n\r\nMateri yang dipelajari :\r\nApa itu Data Preparation atau Data Wrangling?\r\nMissing Value in R\r\nFactor\r\nReading from Text and Excel File\r\nStructure Transformation\r\nPenutup Data Wrangling Part 1', 'dqlab', 'https://academy.dqlab.id/Certificate_check_2/resultV2/DQLABDTWR1TRRPGP', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(187, '4312001085', 'Statistics using R for Data Science', '2021-01-01', NULL, 'Learning Outcome\r\nDasar-dasar ilmu statistik untuk memulai perjalanan data science dengan menggunakan R.\r\n\r\nMateri yang dipelajari :\r\nDasar-dasar Statistik\r\nAnalisis Data Sederhana', 'dqlab', 'https://academy.dqlab.id/Certificate_check_2/resultV2/DQLABINTS1VDAGCO', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(188, '4312001085', 'Fundamental SQL with SELECT Statement', '2022-01-01', NULL, 'Learning Outcome\r\nSQL adalah satu bahasa standar yang digunakan untuk berkomunikasi dengan sistem database yang dominan di dunia saat ini, yaitu sistem database relasional.\r\n\r\nCourse Basic SQL with SELECT Statement ini akan memberikan kepada Anda konsep mengenai sistem database. Kemudian akan berfokus ke bagaimana kita menggunakan SELECT statement untuk mengambil data dengan contoh database yang muda', 'dqlab', 'https://academy.dqlab.id/Certificate_check_2/resultV2/DQLABSQLT1FTMDNB', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(189, '4312001085', 'Introduction to Data Science with R', '2021-01-01', NULL, 'Learning Outcome\r\nModul \'Introduction to Data Science with R\' ini membahas dasar bahasa pemrograman R yang akan dikerjakan dengan menggunakan DQLab LiveCode Editor. Dengan demikian, modul ini dapat menjadi langkah awal menjadi data scientist. \r\n\r\nModul \'Introduction to Data Science with R\' ini membahas dasar bahasa pemrograman R yang akan dikerjakan dengan menggunakan DQLab LiveCode Editor. Dengan de', 'dqlab', 'https://academy.dqlab.id/Certificate_check_2/resultV2/DQLABBGINRKLHOTF', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(190, '4312001085', 'Fundamental Data Visualization using R', '2021-01-01', NULL, 'Learning Outcome\r\nModul ini akan membahas beragam cara memvisualisasikan data, terutama cara memilih grafik yang tepat serta memodifikasinya agar fokus pada pesan yang ingin disampaikan. Modul ini juga akan menuntun kamu untuk memahami elemen-elemen pada grafik sehingga kamu dapat mengubah elemen-elemen tersebut sesuai kebutuhan. Modul ini tidak akan mengajarkan kamu menjadi seorang analis data den', 'dqlab', 'https://academy.dqlab.id/Certificate_check_2/resultV2/DQLABINTR1NQICFV', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
