(439, '4122201110', 'Certificate of Participation – PBL Jasa Raharja', '2024-01-01', NULL, 'Participated in a community engagement program held in collaboration with Jasa Raharja and Polibatam, supporting MSMEs through administrative assistance and documentation.', 'Jasa Raharja &amp; Politeknik Negeri Batam', 'https://polibatam.id/SertifikatJasaRaharjawithPolibatam', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(440, '4132211015', 'Tenaga Muda Ahli Pabean', '2024-01-01', NULL, 'Ujian Sertifikasi Tenaga Muda Ahli Kepabeanan yang diselenggarakan oleh Politeknik Negeri Batam dan Asosiasi Tenaga Ahli Kepabeanan (ATAK) di Batam.', 'Asosiasi Tenaga Ahli Kepabeanan (ATAK)', 'https://polibatam.id/Certificate_Pabean_Bima_Awanda', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
