(442, '3312301034', '[Coding Camp 2025] Certificate', '2025-01-01', NULL, 'Certificate of completion for successfully completing Coding Camp powered by DBS Foundation, specializing in Front-End and Back-End Developer.', 'Coding Camp powered by DBS Foundation', 'https://polibatam.id/CertificateCodingCamp', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(443, '4312201027', 'Talent Polibatam Fair 2024', '2024-01-01', NULL, 'Has participated as a Dance Performer in Polibatam Fair 2024, showcasing creativity in a vibrant artistic performance.', 'Politeknik Negeri Batam', 'https://polibatam.id/sertifikat_dance_polibatam_fair', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(444, '4312201027', 'Wirausaha Merdeka', '2024-01-01', NULL, 'Has participated in the 2024 Wirausaha Merdeka Program by developing a digital game as an entrepreneurial innovation in the creative industry. This program aims to foster entrepreneurial spirit, creativity, and problem-solving skills through a tech-based business project.', 'Politeknik Negeri Batam', 'https://polibatam.id/sertifikat_kompetensi_UMKM_wirausaha_merdeka', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(445, '4312201027', 'E-Learning K3', '2025-01-01', NULL, 'Has completed the e-learning course on Occupational Safety and Health (OSH), aimed at enhancing understanding of basic safety principles, hazard identification, and the implementation of a safe and healthy work culture.', 'Politeknik Negeri Batam', 'https://polibatam.id/sertifikat_e-learning_K3', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(446, '4312201027', 'Panitia Divisi Kakak Pembimbing', '2023-01-01', NULL, 'Served as a Student Mentor in the 2024 Campus Orientation Program, guiding and supporting new students in their transition to academic life while fostering discipline, leadership, and integrity.', 'Kumpulan Anak Seni', 'https://polibatam.id/sertifikat_panitia_divisi_kaka_pembimbing', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
