(448, '4332201023', 'Red Hat Certified System Administrator', '2024-01-01', NULL, 'Topics : Linux Essential Tools, Shell Scripts, Operate Running Systems, File Systems, User And Group Management, Security Configurations, Basic Container Management.', 'Red Hat', 'https://polibatam.id/certfathur1', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(449, '4342211053', 'Docker Introduction', '2024-01-01', NULL, 'This certification demonstrates my foundational understanding of container technology using Docker. The training covered key topics including containerization concepts, Docker architecture, image and container management, and hands-on practices for building and running container-based applications. Through this program, I gained essential skills for managing efficient and scalable development.', 'Jago Institute', 'https://drive.google.com/', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(450, '4342211053', 'PBL Expo participants', '2024-01-01', NULL, 'Awarded for active participation in the Web &amp; Mobile Application category at the PBL Expo held by Politeknik Negeri Batam from August 5–7, 2024. This certificate recognizes involvement in showcasing applied project-based learning innovations through software development and user-oriented design.', 'State Polytechnic of Batam', 'https://drive.google.com/', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(451, '4342211053', 'PBL Expo Consolation Winner', '2024-01-01', NULL, 'Awarded for earning the Juara Harapan (Consolation Winner) in the Web &amp; Mobile Application category during the PBL Expo organized by Politeknik Negeri Batam, held on August 5–7, 2024. This recognition highlights innovative contributions and practical excellence in project-based learning through software development.', 'State Polytechnic of Batam', 'https://drive.google.com/', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(452, '3222311046', 'LEAN SIX SIGMA GREEN BELT CERTIFICATION', '2025-01-01', NULL, 'INDUSTRY RECOGNIZED ACCREDITED SIX SIGMA GREEN BELT CERTIFICATION:\r\n\r\n Authorized Training Partner - PMI®: AIGPE™ is the Official Authorized Training Partner (ATP) of the globally recognized Project Management Institute (PMI®) (Provider No. 5573). The PMI® Authorized Training Partner seal is a registered mark of the Project Management Institute, Inc.', 'AIGPE', 'https://polibatam.id/AIGPESIXSIGMA', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(453, '4332201033', 'RHCSA - System Administrator', '2024-01-01', NULL, 'Successfully earned the Red Hat Certified System Administrator (RHCSA) certification, validating my ability to handle essential system administration tasks required in Red Hat Enterprise Linux environments. This certification demonstrates my skills in areas such as file systems, user and group management, security, networking, and process management.', 'Red Hat', 'https://polibatam.id/RHCSA_RUBEN', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(454, '3312301013', 'Independent Study Program Batch 7 on Android Mobile Development &amp; UI/UX Design', '2024-01-01', NULL, 'This certificate validates participation in the Independent Study Program Batch 7 for Android Mobile Development &amp;amp; UI/UX Design. The recipient has mastered Android app development and UI/UX design principles, demonstrating industry-ready expertise in technology.', 'Infinite Learning', 'https://polibatam.id/Rizqi_TranskripMBKM', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(455, '3312301013', 'Sertifikat Kepesertaan Kampus Merdeka', '2024-01-01', NULL, 'This certificate verifies participation in the Kampus Merdeka Program, an initiative by the Ministry of Education, Culture, Research, and Technology of the Republic of Indonesia. It signifies the recipient&#039;s engagement in a transformative learning experience designed to enhance skills and career readiness.', 'Kemendikbudristek', 'https://polibatam.id/Rizqi_SertifikatKepesertaan_KampusMerdeka', '2026-07-06 20:58:43', '2026-07-06 20:58:43');
