(458, '3312301018', 'MSIB batch 7 membership certificate', '2024-01-01', NULL, 'This certificate acknowledges successful participation in the BATC 7 program, demonstrating the participant skills, knowledge, and commitment to professional development.', 'kemendikbud ristek', 'https://polibatam.id/sertifikat_MSIB', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(459, '3312301018', 'PBL EXPO participation certificate', '2024-01-01', NULL, 'This certificate acknowledges the successful participation in the PBL Expo, recognizing the participant&#039;s involvement and contribution to the event, showcasing their commitment to learning and collaboration.', 'Batam State Polytechnic', 'https://polibatam.id/sertifikat_pblexpo', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(460, '3312301018', 'independent study certificate batch 7', '2024-01-01', NULL, 'This certificate acknowledges the successful participation in the MSIB Studi Independent program at Infinite Learning, recognizing the participant’s dedication, skills, and commitment to independent study and personal growth.', 'Infinite Learning', 'https://polibatam.id/sertifikat_studi_independen', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(461, '3312301010', 'Certificate of Internship Batch 7', '2024-01-01', NULL, 'This certificate is awarded to participants who have successfully completed the Internship Batch 7 program at Infinite Learning with dedication and a strong eagerness to learn. Throughout the program, participants actively contributed to project activities, professional skill development, and demonstrated commitment to continuous learning and self-growth in a professional working environment.', 'Batam State of Polytechnic', 'https://polibatam.id/CertificateInternshipBatch7_AliaPramestiaNurdenia', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(462, '4322201065', 'Master Class 3D Animation', '2022-01-01', NULL, 'A program that will train students in the Animation and Multimedia &amp; Networks study programs in the mechanics of animating 3D objects or characters using Blender. This activity is held over several sessions and is guided by qualified mentors.', 'Batam State Polytechnic', 'https://polibatam.id/Master_Class_Certificate', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(463, '4322201065', 'Merdeka Entrepreneurship Program', '2023-01-01', NULL, 'Independent Entrepreneurship is part of the Independent Campus program of the Ministry of Education, Culture, Research, and Technology (Kemendikbudristek), which provides students with opportunities to learn and develop themselves as aspiring entrepreneurs through activities outside of class.', 'Batam State Polytechnic', 'https://polibatam.id/WMK_Certificate', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(464, '4322201065', 'Independent Study Program Batch 7 on Game Development', '2024-01-01', NULL, 'Game Development is a training and internship program based on work-based learning. Participants will gain industry experience through three project challenges. Each challenge will be completed in groups, with each group member choosing one of three main roles in creating a game application: game programmer, game artist, and level designer.', 'Infinite Learning', 'https://polibatam.id/Game_Development_Certificate', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(465, '3312301010', 'Certificate Participant MSIB Batch 7', '2024-01-01', NULL, 'By incorporating gamification, educators can create a more dynamic and simulating learning environment, which can lead to improved learning outcomes', 'Batam State Polytechnic', 'https://polibatam.id/Certificate_Participation_MSIB', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(466, '3312301010', 'Coder Competition', '2024-01-01', NULL, 'Collaborative Learning significantly impact on student academic performance', 'Batam State Polytechnic', 'https://polibatam.id/Certificate_CoderCompetition', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(467, '3312301010', 'PBL Expo Batam State Polytechnic', '2024-01-01', NULL, 'With Project Website Pakaian Preloved and Website CoETreemine', 'Batam State Polytechnic', 'https://polibatam.id/Certificate_PBLExpo2024', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
