(475, '4312201121', 'OHS Certification', '2025-01-01', NULL, 'This certification strengthened my understanding of creating a safe and compliant work environment, which is essential in any professional field', 'International Labour Organization', 'https://shorturl.at/pDWqI', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(476, '4312201121', 'graphic designer intern', '2025-01-01', NULL, 'a 3-month remote internship as a Graphic Design Intern at GAO Tek Inc.', 'Gaotek.Inc', 'https://shorturl.at/kzlqd', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(477, '4132201064', 'SAP01 - SAP Fundamental Overview', '2024-01-01', NULL, 'In the SAP01 Overview certification, I learned the basics of the SAP ERP Material Management (MM) module, covering purchasing processes, inventory management, goods receipt, and invoice verification. I gained an understanding of the procurement-to-pay (P2P) workflow, creating purchase orders (POs) and requisition forms (RQs), managing material and vendor master data, and integration with the FI/CO', 'Politeknik Negeri Batam', 'https://polibatam.id/SAP01-SAPFundamentalOverview', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(478, '4132201064', 'Sertifikasi Tenaga Muda Ahli Kepabeanan', '2024-01-01', NULL, 'Certification exam Tenaga Muda Ahli Kepabeanan held at the Batam State Polytechnic. Focus on knowledge of customs understanding, customs regulations, and also calculating Nilai Pabean ​​along with finding Pos Tarif in the BTKI Book.', 'Politeknik Negeri Batam', 'https://polibatam.id/SertifikasiTenagaMudaAhliKepabeanan', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
