(624, '4342301037', 'PKM 2024 Funding Certificate', '2024-01-01', NULL, 'This certificate is awarded by the Ministry of Education, Culture, Research, and Technology to a team from Politeknik Negeri Batam for participating in the 2024 Student Creativity Program (PKM) with the “DokterOnTime” application, focused on synchronizing appointments, prescriptions, and medication collection.', 'Politeknik Negeri Batam', 'https://polibatam.id/Piagam-Pendanaan-PKM-2024', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(625, '4342301037', 'Certified Independent Study Program Participant (MSIB Batch 7)', '2024-01-01', NULL, 'Successfully completed the Certified Independent Study Program (MSIB Batch 7), fulfilling all academic and project requirements in a structured industry-based learning environment.', 'Ministry of Education, Culture, Research, and Technology (Kampus Merdeka) in collaboration with PT Kinema Systrans Multimedia', 'https://polibatam.id/SertifikatKepersertaanMSIB_StudiIndependen', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(626, '4342301037', 'Best Project Award – Independent Study Program', '2024-01-01', NULL, 'Awarded for outstanding contribution and performance as a team member (Hacker role) in developing a project during the Independent Study Program Batch 7 in Mobile Development.', 'Infinite Learning (in collaboration with Kampus Merdeka / MSIB Program)', 'https://polibatam.id/best-project-Muhammad-Dzakwan-Naufal', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(627, '4342301037', 'MSIB Batch 7 Completion Certificate (Mobile Development &amp; UI/UX Design)', '2024-01-01', NULL, 'Successfully completed the Independent Study Program Batch 7, specializing in Android Mobile Development and UI/UX Design, including project-based and practical industry learning.', 'Infinite Learning in collaboration with Kampus Merdeka (Ministry of Education, Indonesia)', 'https://polibatam.id/SertifikatMSIB_Muhammad-Dzakwan-Naufal', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(628, '4342301037', 'Certificate of Completion – Project-Based Learning (FabricMatch)', '2025-01-01', NULL, 'Completed a project titled “Innovation of Fabric Color Identification System using Sensor Technology and Mobile IoT Integration for Textile Industry,” focusing on synchronization of threads and fabrics to improve tailoring production processes.', 'Politeknik Negeri Batam', 'https://polibatam.id/FabricMatch-Certificate', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(629, '4342301037', 'Certificate of Completion – Project-Based Learning (Koladi)', '2025-01-01', NULL, 'Completed a project titled “Corporate Digital Transformation: Digital Office Application,” focusing on developing digital solutions to support organizational workflow and transformation.', 'Politeknik Negeri Batam', 'https://polibatam.id/Koladi-Certificate', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
