(21, '4111901111', 'Project Arrange a Standard Operating Procedure', 'Project Leader to Arrange a Standard Operating Procedure', '-', 'https://bit.ly/SOPPolibatamWindy', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(22, '4111901048', 'Project - Management Accounting II', 'In this project, I am tasked with collecting data and compiling analysis reports on the activity resource usage model and tactical decision making and inventory management sections', '-', 'https://polibatam.id/PBL-MA-2', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
(23, '4111901048', 'Scientific Report', 'In this research project, I am tasked with collecting several research references and helping formulate scientific writing, then make a summary related to the outline of the research to be presented to the public.', 'https://drive.google.com/file/d/1wNmzk9ux6Xps8fAgTUbChNtJViNpShS0/view?usp=sharing', 'https://polibatam.id/LKIfraudacademic_OAV', '2026-07-06 20:58:43', '2026-07-06 20:58:43'),
